//! Parity test against upstream (tests/parity/pl-ocr/reference.json, generated by gen_reference.py
//! with the unmodified paperless-ngx v3.4.2 + Pillow 13 + OCRmyPDF 17.12).

use std::cell::RefCell;
use std::path::{Path, PathBuf};

use pl_ocr::args::{ArgsRequest, construct_ocrmypdf_parameters};
use pl_ocr::config::{ArchiveFileGeneration, Clean, ColorConversion, Mode, OcrConfig, OutputType};
use pl_ocr::native::{FsImageOps, merge_sidecars};
use pl_ocr::parser::{OcrBackend, RasterisedParser, should_produce_archive};
use pl_ocr::{OcrArgs, OcrError, Result};
use serde_json::{Value, json};

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/parity/pl-ocr")
}

fn reference() -> Value {
    let p = root().join("reference.json");
    serde_json::from_str(&std::fs::read_to_string(p).expect("reference.json")).expect("json")
}

fn samples() -> PathBuf {
    root().join("samples")
}

fn upstream_samples() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../upstream/src/paperless/tests/samples/tesseract")
}

struct Norm {
    tmp: String,
    samples: Vec<String>,
}

impl Norm {
    fn new(tmp: &Path) -> Self {
        let canon = |p: PathBuf| p.to_string_lossy().replace('\\', "/");
        Norm { tmp: canon(tmp.to_path_buf()), samples: vec![canon(samples()), canon(upstream_samples())] }
    }
    fn s(&self, v: &str) -> String {
        let mut v = v.replace('\\', "/").replace(&self.tmp, "<TMP>");
        for s in &self.samples {
            v = v.replace(s, "<SAMPLES>");
        }
        v
    }
    fn v(&self, v: &Value) -> Value {
        match v {
            Value::String(s) => Value::String(self.s(s)),
            Value::Object(m) => Value::Object(m.iter().map(|(k, x)| (k.clone(), self.v(x))).collect()),
            Value::Array(a) => Value::Array(a.iter().map(|x| self.v(x)).collect()),
            o => o.clone(),
        }
    }
}

/// `DEFAULT_CFG` from gen_reference.py + overrides → OcrConfig.
fn cfg_from(over: &Value, threads: i64) -> OcrConfig {
    let mut c = OcrConfig::defaults();
    c.threads_per_worker = threads;
    c.max_image_pixels_setting = None;
    // upstream default OCR_LANGUAGE (PaperRust default is deu+eng, Known difference 22)
    c.language = "eng".into();
    let Value::Object(m) = over else { return c };
    for (k, v) in m {
        match k.as_str() {
            "mode" => c.mode = Mode::parse(v.as_str().unwrap()).unwrap(),
            "clean" => c.clean = Clean::parse(v.as_str().unwrap()).unwrap(),
            "deskew" => c.deskew = v.as_bool().unwrap(),
            "rotate" => c.rotate = v.as_bool().unwrap(),
            "rotate_threshold" => c.rotate_threshold = v.as_f64().unwrap(),
            "pages" => c.pages = v.as_i64(),
            "output_type" => c.output_type = OutputType::parse(v.as_str().unwrap()).unwrap(),
            "color_conversion_strategy" => c.color_conversion_strategy = ColorConversion::parse(v.as_str().unwrap()).unwrap(),
            "max_image_pixel" => c.max_image_pixel = v.as_f64(),
            "user_args" => c.user_args = Some(v.clone()),
            "language" => c.language = v.as_str().unwrap().to_string(),
            "image_dpi" => c.image_dpi = v.as_i64(),
            "archive_file_generation" => c.archive_file_generation = ArchiveFileGeneration::parse(v.as_str().unwrap()).unwrap(),
            other => panic!("unknown cfg key {other}"),
        }
    }
    c
}

/// make JSON numbers comparable (12.0 vs 12, 2.5000005 …).
fn num_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => (x.as_f64().unwrap() - y.as_f64().unwrap()).abs() < 1e-9,
        (Value::Object(x), Value::Object(y)) => x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).is_some_and(|w| num_eq(v, w))),
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y).all(|(v, w)| num_eq(v, w)),
        _ => a == b,
    }
}

#[test]
fn image_probes_match_pillow() {
    let r = reference();
    let mut diffs = Vec::new();
    for (name, exp) in r["images"].as_object().unwrap() {
        let path = match name.strip_prefix("upstream:") {
            Some(n) => upstream_samples().join(n),
            None => samples().join(name),
        };
        let ops = FsImageOps { tempdir: std::env::temp_dir(), pixel_limit: pl_ocr::imageinfo::pil_pixel_limit(None) };
        let p = path.to_string_lossy();
        use pl_ocr::args::ImageOps;
        let got = json!({
            "get_dpi": ops.get_dpi(&p),
            "calculate_a4_dpi": ops.calculate_a4_dpi(&p),
            "has_alpha": ops.has_alpha(&p).map(Value::Bool).unwrap_or_else(|e| json!(format!("ERR {}", e.class_name()))),
        });
        for k in ["get_dpi", "calculate_a4_dpi", "has_alpha"] {
            if got[k] != exp[k] {
                diffs.push(format!("{name}.{k}: got {} want {}", got[k], exp[k]));
            }
        }
        let info = pl_ocr::imageinfo::probe_path(&path).unwrap();
        if json!([info.width, info.height]) != exp["size"] {
            diffs.push(format!("{name}.size: got {}x{} want {}", info.width, info.height, exp["size"]));
        }
    }
    assert!(diffs.is_empty(), "{} Abweichungen:\n{}", diffs.len(), diffs.join("\n"));
}

#[test]
fn ocrmypdf_args_match_upstream() {
    let r = reference();
    let tmp = tempfile::tempdir().unwrap();
    let n = Norm::new(tmp.path());
    let mut diffs = Vec::new();
    let cases = r["args"].as_array().unwrap();
    for (i, case) in cases.iter().enumerate() {
        let cfg = cfg_from(&case["cfg"], 2);
        let input = match case["sample"].as_str() {
            Some(s) => samples().join(s).to_string_lossy().into_owned(),
            None => "input.pdf".to_string(),
        };
        let images = FsImageOps { tempdir: tmp.path().to_path_buf(), pixel_limit: pl_ocr::imageinfo::pil_pixel_limit(None) };
        let req = ArgsRequest {
            input_file: &input,
            mime_type: case["mime"].as_str().unwrap(),
            output_file: "output.pdf",
            sidecar_file: "sidecar.txt",
            safe_fallback: case["safe_fallback"].as_bool().unwrap(),
            skip_text: case["skip_text"].as_bool().unwrap(),
        };
        match construct_ocrmypdf_parameters(&cfg, &req, &images) {
            Ok(a) => {
                let got = n.v(&a.to_json());
                let keys: Vec<&str> = a.keys();
                if !num_eq(&got, &case["args"]) || json!(keys) != case["keys"] {
                    diffs.push(format!("#{i} {}:\n got  {got}\n want {}", case["cfg"], case["args"]));
                }
            }
            Err(e) => {
                let got = format!("{}: {}", e.class_name(), e.message());
                if Some(got.as_str()) != case["error"].as_str() {
                    diffs.push(format!("#{i}: error {got} want {}", case["error"]));
                }
            }
        }
    }
    assert!(diffs.is_empty(), "{}/{} Abweichungen:\n{}", diffs.len(), cases.len(), diffs.join("\n"));
}

struct Mock {
    texts: RefCell<Vec<Option<String>>>,
    tagged: bool,
    ocr: RefCell<Vec<Option<String>>>,
    calls: RefCell<Vec<Value>>,
    extract_calls: RefCell<Vec<Option<String>>>,
    img2pdf: Option<String>,
    gs: Option<String>,
    tmp: PathBuf,
}

fn py_exc(name: &str) -> OcrError {
    match name {
        "DigitalSignatureError" => OcrError::DigitalSignature,
        "EncryptedPdfError" => OcrError::EncryptedPdf,
        "PriorOcrFoundError" => OcrError::PriorOcrFound("page already has text!".into()),
        "InputFileError" => OcrError::InputFile("bad input".into()),
        "TaggedPDFError" => OcrError::InputFile("This PDF is marked as a Tagged PDF.".into()),
        "SubprocessOutputError" => OcrError::SubprocessOutput("Ghostscript PDF/A rendering failed".into()),
        "SubprocessOutputError2" => OcrError::SubprocessOutput("tesseract crashed".into()),
        "ValueError" => OcrError::Config("boom".into()),
        o => panic!("unknown exception {o}"),
    }
}

impl OcrBackend for Mock {
    fn extract_pdf_text(&self, _: &Path) -> Option<String> {
        unreachable!()
    }
    fn is_tagged_pdf(&self, _: &Path) -> bool {
        self.tagged
    }
    fn ocr(&self, args: &OcrArgs) -> Result<()> {
        self.calls.borrow_mut().push(args.to_json());
        let mut o = self.ocr.borrow_mut();
        if o.is_empty() {
            return Ok(());
        }
        match o.remove(0) {
            Some(e) => Err(py_exc(&e)),
            None => Ok(()),
        }
    }
    fn convert_image_to_pdfa(&self, _: &Path, _: &OcrConfig, _: &Path) -> Result<PathBuf> {
        match &self.img2pdf {
            Some(e) => Err(py_exc(e)),
            None => Ok(self.tmp.join("archive.pdf")),
        }
    }
    fn convert_pdf_to_pdfa(&self, _: &Path, _: &Path, _: &OcrConfig) -> Result<()> {
        match &self.gs {
            Some(e) => Err(py_exc(e)),
            None => Ok(()),
        }
    }
    fn extract_text(&self, sidecar: Option<&Path>, _: &Path, _: Mode) -> Option<String> {
        self.extract_calls.borrow_mut().push(sidecar.map(|p| p.to_string_lossy().into_owned()));
        let mut t = self.texts.borrow_mut();
        if t.len() > 1 { t.remove(0) } else { t.first().cloned().flatten() }
    }
}

#[test]
fn parse_control_flow_matches_upstream() {
    let r = reference();
    let tmp = tempfile::tempdir().unwrap();
    let n = Norm::new(tmp.path());
    let mut diffs = Vec::new();
    let cases = r["parse"].as_array().unwrap();
    for (i, s) in cases.iter().enumerate() {
        let mut over = s.get("cfg").cloned().unwrap_or(json!({}));
        over["mode"] = s["mode"].clone();
        let cfg = cfg_from(&over, 1);
        let mock = Mock {
            texts: RefCell::new(s["texts"].as_array().unwrap().iter().map(|v| v.as_str().map(str::to_string)).collect()),
            tagged: s["tagged"].as_bool().unwrap(),
            ocr: RefCell::new(s["ocr"].as_array().unwrap().iter().map(|v| v.as_str().map(str::to_string)).collect()),
            calls: RefCell::new(Vec::new()),
            extract_calls: RefCell::new(Vec::new()),
            img2pdf: s.get("img2pdf").and_then(Value::as_str).map(str::to_string),
            gs: s.get("gs").and_then(Value::as_str).map(str::to_string),
            tmp: tmp.path().to_path_buf(),
        };
        let images = FsImageOps { tempdir: tmp.path().to_path_buf(), pixel_limit: pl_ocr::imageinfo::pil_pixel_limit(None) };
        let parser = RasterisedParser { settings: cfg, tempdir: tmp.path().to_path_buf(), backend: &mock, images: &images };
        let doc = match s.get("sample").and_then(Value::as_str) {
            Some(x) => samples().join(x),
            None => PathBuf::from("doc.pdf"),
        };
        let res = parser.parse(&doc, s["mime"].as_str().unwrap(), s["produce"].as_bool().unwrap());
        let got = match res {
            Ok(o) => json!({
                "text": o.text,
                "archive": o.archive_path.map(|p| n.s(&p.to_string_lossy())),
            }),
            Err(e) => json!({"error": format!("ParseError: {}", e.message())}),
        };
        let want =
            if s.get("error").is_some() { json!({"error": s["error"]}) } else { json!({"text": s["text"], "archive": s["archive"]}) };
        let calls = n.v(&Value::Array(mock.calls.borrow().clone()));
        let extract = n.v(&json!(*mock.extract_calls.borrow()));
        if got != want || !num_eq(&calls, &s["calls"]) || extract != s["extract_calls"] {
            diffs.push(format!(
                "#{i} mode={} produce={} mime={} ocr={}:\n got  {got} calls={calls} extract={extract}\n want {want} calls={} extract={}",
                s["mode"], s["produce"], s["mime"], s["ocr"], s["calls"], s["extract_calls"]
            ));
        }
    }
    assert!(diffs.is_empty(), "{}/{} Abweichungen:\n{}", diffs.len(), cases.len(), diffs.join("\n"));
}

#[test]
fn text_helpers_match_upstream() {
    let r = reference();
    for c in r["post_process_text"].as_array().unwrap() {
        let got = pl_ocr::text::post_process_text(c["in"].as_str());
        assert_eq!(json!(got), c["out"], "post_process_text({:?})", c["in"]);
    }
    for c in r["read_file"].as_array().unwrap() {
        let hex = c["hex"].as_str().unwrap();
        let bytes: Vec<u8> = (0..hex.len()).step_by(2).map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap()).collect();
        assert_eq!(json!(pl_ocr::text::decode_text_bytes(&bytes)), c["out"], "read_file({hex})");
    }
    for c in r["sidecars"].as_array().unwrap() {
        let pages: Vec<Option<String>> = c["pages"].as_array().unwrap().iter().map(|v| v.as_str().map(str::to_string)).collect();
        assert_eq!(json!(merge_sidecars(&pages)), c["merged"], "merge_sidecars({:?})", c["pages"]);
    }
}

#[test]
fn should_produce_archive_matches_upstream() {
    let r = reference();
    for c in r["should_produce_archive"].as_array().unwrap() {
        let born = c["born_digital"].as_bool().unwrap();
        let got = should_produce_archive(
            c["requires_pdf_rendition"].as_bool().unwrap(),
            c["can_produce_archive"].as_bool().unwrap(),
            ArchiveFileGeneration::parse(c["generation"].as_str().unwrap()).unwrap(),
            c["mime"].as_str().unwrap(),
            || born,
        );
        assert_eq!(json!(got), c["result"], "{c}");
    }
}
